-- Βιβλιοθήκη: ελληνικός τίτλος των κατευθυντήριων οδηγιών (title_el).
--   Στα ελληνικά η λίστα δείχνει τον ελληνικό τίτλο και από κάτω τον πρωτότυπο· στα αγγλικά μόνο
--   τον πρωτότυπο. Οι ελληνόγλωσσες οδηγίες κρατούν το όνομά τους. Το νοσοκομείο συμπληρώνει
--   προαιρετικά τον ελληνικό τίτλο στις δικές του οδηγίες (φόρμα εγγραφής).
-- Μόνο προσθήκη στήλης και ενημέρωση των οδηγιών της πλατφόρμας.

alter table public.library_items add column if not exists title_el text check (title_el is null or length(btrim(title_el)) > 1);

update public.library_items set title_el = $q$Surviving Sepsis Campaign: Διεθνείς οδηγίες για την αντιμετώπιση της σήψης και της σηπτικής καταπληξίας 2026$q$, updated_at = now() where organization_id is null and kind = 'guideline' and name = $q$Surviving Sepsis Campaign: International Guidelines for Management of Sepsis and Septic Shock 2026$q$ and title_el is null;
